# Stray positions in transformed coords vs target cells in O: brute force dihedral transforms on rel-coords then fold across nearest edge.
# First: compute outside strays per pair, then try candidate targets = reflect across the NEAREST edge of transformed frame bbox in TRANSFORMED coordinate space.
def solve(I,tn,mode='nearest'):
    I=np.array(I); out=TR[tn](I)
    vals,cnts=np.unique(out,return_counts=True); bg=vals[cnts.argmax()]
    lab,n=ndimage.label(out==1); sizes=ndimage.sum(np.ones_like(lab),lab,range(1,n+1))
    best=int(np.argmax(sizes))+1; y,x=np.where(lab==best)
    ys0,xs0=int(y.min()),int(x.min()); H,W=out.shape
    res=out.copy()
    sc=(out!=1)&(out!=bg); yy,xx=np.where(sc)
    for yy_,xx_ in zip(yy,xx):
        v=int(out[yy_,xx_]); rr,cc=int(yy_-ys0),int(xx_-xs0)
        if 0<=rr<H and 0<=cc<W: continue
        cand=[]
        # reflection across the nearest EDGE (choose min over 4 sides via manhattan distance to edge lines)
        dists={'top':abs(rr),'bottom':abs(rr-(H-1)),'left':abs(cc),'right':abs(cc-(W-1))}
        near=min(dists,key=dists.get)
        if near=='top': cand.append((-rr,cc))           # mirror above top
        elif near=='bottom': cand.append((2*H-1-rr,cc))
        if near=='left': cand.append((rr,-cc))
        elif near=='right': cand.append((rr,2*W-1-cc))
        if len(cand)>1: cand.append(None)
        tgt=None
        if near=='top' and rr<0: tgt=(-rr,cc)
        elif near=='bottom' and rr>=H: tgt=(2*H-1-rr,cc)
        elif near=='left' and cc<0: tgt=(rr,-cc)
        elif near=='right' and cc>=W: tgt=(rr,2*W-1-cc)
        if tgt:
            res[tgt]=v
    return res
for p,tn in names.items():
    I=G[f'Demo pair {p} input']; O=np.array(G[f'Demo pair {p} output'])
    R=solve(I,tn)
